import { readFile } from "node:fs/promises";
import path from "node:path";
import Fuse from "fuse.js";

/**
 * Server-side full-text search for the site-wide dialog.
 *
 * The corpus is public/search-index.json, generated by
 * scripts/build-search-index.mjs at build time (title, description, tag labels
 * and the full plain-text body of every post and page). It is read here and
 * never shipped to the browser: the client asks for results, not for the
 * index. Keeping it on the server also means a future corpus growth does not
 * turn into a first-keystroke download.
 *
 * Fuse runs per request over a parsed-in-memory index. That is deliberately
 * simple: 65 documents and ~350 KB, one fuzzy pass, no embedding service, no
 * extra dependency. The response is private/no-store because it is a function
 * of the query and not shared between readers.
 */

const FUSE_OPTIONS = {
  keys: [
    { name: "title", weight: 1 },
    { name: "tagLabels", weight: 0.8 },
    { name: "description", weight: 0.7 },
    { name: "body", weight: 0.5 },
  ],
  // Matches anywhere, not just near the start — the body is long and the phrase
  // the reader remembers is usually in the middle.
  ignoreLocation: true,
  threshold: 0.32,
  minMatchCharLength: 2,
  includeMatches: true,
  includeScore: true,
};

const RESULT_LIMIT = 12;
const SNIPPET_LENGTH = 152;

let indexPromise = null;
function getIndex() {
  if (!indexPromise) {
    indexPromise = readFile(
      path.join(process.cwd(), "public", "search-index.json"),
      "utf8"
    )
      .then((raw) => JSON.parse(raw))
      .catch((error) => {
        // Do not memoise a failed read: a missing index (first dev boot before
        // the predev script ran) should recover on the next request.
        indexPromise = null;
        throw error;
      });
  }
  return indexPromise;
}

let fusePromise = null;
async function getFuse() {
  if (!fusePromise) {
    fusePromise = getIndex()
      .then((items) => new Fuse(items, FUSE_OPTIONS))
      .catch((error) => {
        fusePromise = null;
        throw error;
      });
  }
  return fusePromise;
}

export async function GET(request) {
  const started = performance.now();
  const { searchParams } = new URL(request.url);
  const q = (searchParams.get("q") || "").trim().slice(0, 80);

  if (q.length < 2) {
    return Response.json(
      { q, results: [], took: 0 },
      { headers: { "Cache-Control": "private, no-store" } }
    );
  }

  let fuse;
  try {
    fuse = await getFuse();
  } catch {
    return Response.json(
      { q, results: [], error: "index-unavailable" },
      { status: 503, headers: { "Cache-Control": "private, no-store" } }
    );
  }

  const results = fuse
    .search(q, { limit: RESULT_LIMIT })
    .map(({ item, matches }) => ({
      type: item.type,
      href: item.href,
      title: item.title,
      description: item.description,
      date: item.dateLabel || "",
      read: item.read || "",
      tags: item.tagLabels || [],
      snippet: buildSnippet(item, matches),
    }))
    /* Group posts before pages, preserving Fuse's score order inside each
       group. The dialog renders the two groups separately, so this makes its
       "文章" / "页面" sections fall out without a second pass on the client. */
    .sort((a, b) => (a.type === "post" ? 0 : 1) - (b.type === "post" ? 0 : 1));

  return Response.json(
    { q, results, took: Math.round(performance.now() - started) },
    { headers: { "Cache-Control": "private, no-store" } }
  );
}

/**
 * A window of body text around the first hit, split into highlighted and plain
 * segments. If the match was in the title/tags/description only, the body's
 * opening is shown unhighlighted — the result still needs context.
 */
function buildSnippet(item, matches) {
  const body = item.body || "";
  const bodyMatch = matches?.find((match) => match.key === "body");
  const indices = (bodyMatch?.indices || [])
    .slice(0, 3)
    .sort((a, b) => a[0] - b[0]);

  if (!indices.length) {
    const fallback = (item.description || body).trim().slice(0, SNIPPET_LENGTH - 32);
    return fallback ? [{ text: fallback, hit: false }] : [];
  }

  const first = indices[0][0];
  let start = Math.max(0, first - 52);
  let end = Math.min(body.length, start + SNIPPET_LENGTH);
  if (end - start < 110) start = Math.max(0, end - 130);

  const text = body.slice(start, end);
  const segments = [];
  let cursor = 0;

  for (const [from, to] of indices) {
    const hitStart = Math.max(0, from - start);
    const hitEnd = Math.min(text.length, to + 1 - start);
    if (hitEnd <= cursor || hitStart >= text.length) continue;
    if (hitStart > cursor) {
      segments.push({ text: text.slice(cursor, hitStart), hit: false });
    }
    segments.push({ text: text.slice(hitStart, hitEnd), hit: true });
    cursor = hitEnd;
  }
  if (cursor < text.length) {
    segments.push({ text: text.slice(cursor), hit: false });
  }

  return segments;
}
